import org.audiveris.omr.sheet.Book;
import java.nio.file.*;import java.util.*;
public class RealArticulationSupportImageProbe extends RealLedgerMembershipImageProbe {
 private final Object actual;
 public RealArticulationSupportImageProbe(Book book,SortedSet<Integer> ids){super(book,ids);actual=book;}
 private static String stage(Object sheet,String name)throws Exception{List<String> systems=new ArrayList<>();for(Object sys:(List<?>)call(sheet,"getSystems")){Object sig=call(sys,"getSig");List<String> nodes=new ArrayList<>();for(Object n:(Collection<?>)call(sig,"inters",c("sig.inter.ArticulationInter"))){List<String> relations=new ArrayList<>();for(Object e:(Set<?>)call(sig,"edgesOf",n)){Object ch=call(sig,"getOppositeInter",n,e);relations.add("{\"kind\":\""+e.getClass().getSimpleName()+"\",\"opposite_kind\":\""+ch.getClass().getSimpleName()+"\",\"bounds\":"+rect(call(ch,"getBounds"))+",\"relation_grade\":"+call(e,"getGrade")+",\"partner_grade\":"+call(ch,"getGrade")+",\"partner_contextual_grade\":"+call(ch,"getContextualGrade")+"}");}Object cg=call(n,"getContextualGrade");nodes.add("{\"shape\":\""+call(n,"getShape")+"\",\"bounds\":"+rect(call(n,"getBounds"))+",\"grade\":"+call(n,"getGrade")+",\"contextual_grade\":"+(cg==null?"null":cg)+",\"relations\":["+String.join(",",relations)+"]}");}systems.add("{\"system\":"+call(sys,"getId")+",\"articulations\":["+String.join(",",nodes)+"]}");}return "{\"stage\":\""+name+"\",\"systems\":["+String.join(",",systems)+"]}";}
 public void process(){try{Object stub=((List<?>)call(actual,"getStubs")).get(0);call(stub,"reachStep",c("step.OmrStep").getField("SYMBOLS").get(null),false);Object sheet=call(stub,"getSheet");List<String> stages=new ArrayList<>();stages.add(stage(sheet,"SYMBOLS"));for(Object sys:(List<?>)call(sheet,"getSystems"))call(call(sys,"getSig"),"contextualize");stages.add(stage(sheet,"CONTEXTUALIZED"));for(Object sys:(List<?>)call(sheet,"getSystems"))call(make("sig.SigReducer",sys,true),"contextualizeAndPurge");stages.add(stage(sheet,"WEAK_PURGED"));for(Object sys:(List<?>)call(sheet,"getSystems"))call(make("sig.SigReducer",sys,true),"checkArticulations");stages.add(stage(sheet,"REDUNDANCY_CHECKED"));call(stub,"reachStep",c("step.OmrStep").getField("LINKS").get(null),false);stages.add(stage(sheet,"LINKS"));Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"scope\":\"fresh unchanged image SYMBOLS -> explicit original contextualize/weak purge/checkArticulations -> ordinary LINKS, no native input; intermediate calls precede ordinary overlap preparation\",\"stages\":["+String.join(",",stages)+"]}\n");}catch(Exception e){throw new RuntimeException(e);}}
}
